-- 1. LIMPAR TODOS OS PRODUTOS ATUAIS (exceto os que têm pedidos - desativa)
UPDATE produtos SET ativo = false WHERE id NOT IN (
  SELECT DISTINCT produto_id FROM itens_pedido WHERE produto_id IS NOT NULL
);

-- Deletar produtos sem pedidos
DELETE FROM produtos WHERE ativo = false AND id NOT IN (
  SELECT DISTINCT produto_id FROM itens_pedido WHERE produto_id IS NOT NULL
);

